package web

import (
	"crypto/sha256"
	"embed"
	"encoding/hex"
	"io/fs"
	"net/http"
	"time"
)

// staticFS holds everything the browser downloads: Tailwind CSS (generated by
// `go generate`), Datastar (vendored and pinned, see AGENTS.md), the bundled CodeMirror island and the brand SVGs.
//
//go:embed static
var staticFS embed.FS

// assets maps a static file to a URL carrying a content hash, so the browser
// can cache it forever and still pick up a new build.
type assets struct{ hashes map[string]string }

func newAssets() assets {
	a := assets{hashes: map[string]string{}}
	_ = fs.WalkDir(staticFS, "static", func(p string, d fs.DirEntry, err error) error {
		if err != nil || d.IsDir() {
			return err
		}
		b, err := staticFS.ReadFile(p)
		if err != nil {
			return err
		}
		sum := sha256.Sum256(b)
		a.hashes[p[len("static/"):]] = hex.EncodeToString(sum[:4])
		return nil
	})
	return a
}

// URL returns the public URL of a static file ("app.css", "brand/logo.svg").
func (a assets) URL(name string) string {
	if h, ok := a.hashes[name]; ok {
		return "/static/" + name + "?v=" + h
	}
	return "/static/" + name
}

func staticHandler() http.Handler {
	sub, _ := fs.Sub(staticFS, "static")
	files := http.FileServerFS(sub)
	return http.StripPrefix("/static/", http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Cache-Control", "public, max-age="+year)
		w.Header().Set("Expires", time.Now().Add(365*24*time.Hour).UTC().Format(http.TimeFormat))
		files.ServeHTTP(w, r)
	}))
}

const year = "31536000"
